package io.forgeloop.control.integrations.github;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import io.forgeloop.control.application.*;import io.forgeloop.control.domain.*;import java.util.Optional;import org.junit.jupiter.api.Test;
class GithubRunnerCheckoutServiceTest{
 @Test void grantIsBoundToLeaseRepositoryAndInstallation(){TaskLeaseService leases=mock(TaskLeaseService.class);DeliveryTaskRepository tasks=mock(DeliveryTaskRepository.class);RepositoryConnectionService connections=mock(RepositoryConnectionService.class);GithubApi github=mock(GithubApi.class);AuditLedgerService audit=mock(AuditLedgerService.class);DeliveryTask task=mock(DeliveryTask.class);FeatureRun run=mock(FeatureRun.class);RepositoryConnection connection=mock(RepositoryConnection.class);when(leases.requireActiveTaskId("lease","runner","nonce")).thenReturn("task");when(tasks.findById("task")).thenReturn(Optional.of(task));when(task.getRepository()).thenReturn("acme/app");when(task.getBaseBranch()).thenReturn("main");when(task.getRun()).thenReturn(run);when(run.getId()).thenReturn("run");when(connections.requireEnabled("acme/app")).thenReturn(connection);when(connection.getInstallationId()).thenReturn(7L);when(github.issueInstallationToken(7L)).thenReturn("token");GithubCheckoutGrant grant=new GithubRunnerCheckoutService(leases,tasks,connections,github,audit).grant("lease","runner","nonce");assertEquals("acme/app",grant.repository());assertEquals("main",grant.baseBranch());assertEquals("token",grant.token());verify(audit).record("RUNNER_GITHUB_CHECKOUT_GRANTED","FEATURE_RUN","run","runner|acme/app");}
}
